public class Main {
    static int[][] intervalIntersectionBrute(int[][] firstList, int[][] secondList) {
        List<int[]> result = new ArrayList<>();
        for (int[] a : firstList) {
            for (int[] b : secondList) {                        // check every pair directly
                int lo = Math.max(a[0], b[0]), hi = Math.min(a[1], b[1]);
                if (lo <= hi) result.add(new int[]{lo, hi});
            }
        }
        return result.toArray(new int[0][]);
    }
}

